+[[maybe_unused]] static int
+scalar_compress(const simdutf::ppc64::vector_u8 data, uint16_t nmask,
+                char *output) {
+  char tmp[16];
+  data.store(tmp);
+
+  int j = 0;
+  for (int i = 0; i < 16; i++) {
+    if ((nmask & 0x1) == 0) {
+      output[j++] = tmp[i];
+    }
+
+    nmask >>= 1;
+  }
+
+  return j;
+}
